class Commands {
    Input::Connection mark_;
    Input::Scope scope_;
public:
    Commands(Input::System& input) {
        input.Bind({"Mark", Input::Context::Game,
                    {Keys::Control, Keys::M}});
        mark_ = input.Subscribe(scope_,
            Input::Context::Game, "Mark",
            Input::Phase::Pressed,
            [this](const Input::Event&) { Mark(); });
    }
    void Mark();
};

// Тот же обработчик действия Mark
input.Unbind(Input::Context::Game, "Mark");
input.Bind({"Mark", Input::Context::Game,
            {Keys::Alt, Keys::K, Keys::J}});

